  "fr": { "title": "Le Maroc a-t-il renoncé à la finale du Mondial 2030 ? Une source officielle tranche le débat", "excerpt": "Précisions officielles sur la répartition des matches de la prochaine Coupe du monde entre pays organisateurs.",
    "body": ["Une polémique autour d'un possible renoncement du Maroc à l'organisation d'un match majeur de la Coupe du monde 2030 a suscité un large débat parmi les observateurs.", "Une source officielle a tranché la question, affirmant que la répartition des matches entre les trois pays hôtes est toujours en cours d'examen final par les instances footballistiques internationales."] },
