  "fr": { "title": "Nouvelle hausse des transferts des Marocains résidant à l'étranger", "excerpt": "Des indicateurs positifs reflétant la dynamique financière continue des transferts de la diaspora.",
    "body": ["Les transferts des Marocains résidant à l'étranger ont enregistré une nouvelle hausse récemment, selon des données économiques récentes.", "Ces transferts constituent un apport essentiel à l'économie nationale, contribuant de manière significative au soutien des réserves de change du Royaume."] },
